INSERT INTO traces (id, timestamp, user_input, retrieved_chunks, prompt_version, model_output, latency_ms, input_tokens, output_tokens, error) VALUES ('61c02746-f155-5aa9-bb37-72b58a0a0f32', strftime('%Y-%m-%dT', 'now', '-0 days') || '09' || strftime(':%M:%SZ', 'now'), 'The temperature monitoring log for Cold Room CR-03 is missing entries for the period 06:00–14:00 yesterday. The room holds finished product stability samples and three retained injectable batches.', '[]', 'v1', '{"classification": "Environmental", "severity": "High", "impact": "Potential loss of cold-chain integrity for retained injectable batches and stability samples.", "immediate_action": "Quarantine affected batches. Retrieve continuous logger data to confirm actual temperature. Notify QA immediately.", "qa_escalation": true, "missing_info": "Continuous data logger readings for the gap period.", "draft_summary": "A gap in the paper temperature log for CR-03 (06:00\u201314:00) was identified. Continuous logger data must be reviewed to confirm excursion status before any disposition decision."}', 4230, 812, 198, NULL);
INSERT INTO traces (id, timestamp, user_input, retrieved_chunks, prompt_version, model_output, latency_ms, input_tokens, output_tokens, error) VALUES ('fb6cc430-294e-5012-970f-1856ef128226', strftime('%Y-%m-%dT', 'now', '-1 days') || '11' || strftime(':%M:%SZ', 'now'), 'An analyst completed the in-process dissolution test for Batch TAB-1177 without performing the required media deaeration step as specified in STP-022. Results have been entered into the LIMS and are pending QA approval.', '[]', 'v1', '{"classification": "Laboratory", "severity": "Medium", "impact": "Dissolution results may be artificially elevated or depressed. Data integrity concern as results are already in LIMS.", "immediate_action": "Place LIMS results on hold. Repeat dissolution test with deaeration. Raise CAPA for analyst retraining on STP-022.", "qa_escalation": true, "missing_info": "None", "draft_summary": "The deaeration step in STP-022 was omitted during dissolution testing for TAB-1177. All results are on hold pending retest with the correct method."}', 3870, 796, 187, NULL);
INSERT INTO traces (id, timestamp, user_input, retrieved_chunks, prompt_version, model_output, latency_ms, input_tokens, output_tokens, error) VALUES ('9c63f5b7-c958-59a0-87c4-ded78caa0cf7', strftime('%Y-%m-%dT', 'now', '-1 days') || '14' || strftime(':%M:%SZ', 'now'), 'During final packaging inspection for Batch PKG-0892, the QA line inspector found that the secondary carton label shows Lot No. PKG-0829 instead of the correct PKG-0892. Approximately 3,200 units have already been labelled.', '[]', 'v1', '{"classification": "Labelling", "severity": "High", "impact": "Mislabelled product cannot be distributed. Risk of mix-up if units leave the site.", "immediate_action": "Stop packaging line. Quarantine all 3,200 labelled units. Confirm no units have left the warehouse. Initiate relabelling under QA supervision.", "qa_escalation": true, "missing_info": "Confirmation of whether any units reached the warehouse dispatch area.", "draft_summary": "Incorrect lot number (PKG-0829) was printed on secondary cartons for Batch PKG-0892. 3,200 units quarantined; relabelling authorised by QA pending root cause investigation."}', 4110, 824, 201, NULL);
INSERT INTO traces (id, timestamp, user_input, retrieved_chunks, prompt_version, model_output, latency_ms, input_tokens, output_tokens, error) VALUES ('f82b74a6-64f6-5a5a-8002-68af4f89d696', strftime('%Y-%m-%dT', 'now', '-2 days') || '09' || strftime(':%M:%SZ', 'now'), 'The autoclave used for sterilising equipment in the aseptic fill suite triggered a high-pressure abort alarm mid-cycle during a sterilisation run for Batch INJ-0044. The cycle aborted at 78% completion.', '[]', 'v1', '{"classification": "Equipment", "severity": "High", "impact": "Equipment components may not be sterile. Batch INJ-0044 cannot proceed until sterilisation is confirmed.", "immediate_action": "Quarantine all components from the aborted run. Do not use until re-sterilised. Remove autoclave from service and initiate equipment investigation.", "qa_escalation": true, "missing_info": "Engineering fault code from the autoclave PLC log.", "draft_summary": "Autoclave AB-07 aborted a sterilisation cycle at 78% due to a high-pressure alarm. All affected components quarantined; equipment under investigation."}', 3950, 803, 195, NULL);
INSERT INTO traces (id, timestamp, user_input, retrieved_chunks, prompt_version, model_output, latency_ms, input_tokens, output_tokens, error) VALUES ('5389ce84-e861-56e7-8048-dfe64cd75617', strftime('%Y-%m-%dT', 'now', '-3 days') || '13' || strftime(':%M:%SZ', 'now'), 'Operator on Filling Line 2 recorded a fill volume of 5.12 mL for Batch LIQ-0307 against a specification of 5.00 ± 0.10 mL. Two consecutive IPC checks both showed the same over-fill. The line has been stopped.', '[]', 'v1', '{"classification": "Process", "severity": "Medium", "impact": "Batch may be out-of-specification on fill volume. Regulatory label claim is 5 mL; over-fill may create compliance risk.", "immediate_action": "Retain all filled vials since last in-spec IPC. Recalibrate filling heads and recheck against specification before restarting.", "qa_escalation": true, "missing_info": "Volume of product filled since the last in-spec IPC check.", "draft_summary": "Fill volume for LIQ-0307 recorded at 5.12 mL (spec 5.00 \u00b1 0.10 mL) on two consecutive checks. Line stopped; vials quarantined pending filling head recalibration."}', 4080, 811, 193, NULL);
INSERT INTO traces (id, timestamp, user_input, retrieved_chunks, prompt_version, model_output, latency_ms, input_tokens, output_tokens, error) VALUES ('5dbaeec4-7e88-514c-8ad8-718a656c12d8', strftime('%Y-%m-%dT', 'now', '-3 days') || '16' || strftime(':%M:%SZ', 'now'), 'A gowning audit of the Grade B anteroom found that one operator entered the cleanroom without completing the required glove sanitisation step. The operator had already been in the Grade B area for approximately 15 minutes.', '[]', 'v1', '{"classification": "Environmental", "severity": "Medium", "impact": "Potential contamination risk in Grade B area. Batches being processed during the exposure window may be affected.", "immediate_action": "Identify all batches processed during the exposure window. Perform environmental monitoring of the affected area. Operator retraining required.", "qa_escalation": true, "missing_info": "Which batches were being processed in the Grade B area during the 15-minute window.", "draft_summary": "An operator entered Grade B without completing glove sanitisation and remained for 15 minutes. Environmental monitoring initiated; affected batches under review."}', 3760, 788, 184, NULL);
INSERT INTO traces (id, timestamp, user_input, retrieved_chunks, prompt_version, model_output, latency_ms, input_tokens, output_tokens, error) VALUES ('38de89bc-02c4-5d95-a7d1-47df0bd1fc37', strftime('%Y-%m-%dT', 'now', '-4 days') || '10' || strftime(':%M:%SZ', 'now'), 'The calibration certificate for balance BA-12 expired three days ago. The balance was used for three routine IPC weighing checks on Batch GRN-0218 before the expiry was noticed.', '[]', 'v1', '{"classification": "Equipment", "severity": "Low", "impact": "Weighing data from IPC checks may be unreliable. Risk is low as balance calibration rarely drifts significantly over 3 days.", "immediate_action": "Withdraw BA-12 from service and send for immediate recalibration. Review IPC weighing data against historical calibration drift data for this balance.", "qa_escalation": false, "missing_info": "Historical calibration drift records for BA-12.", "draft_summary": "Balance BA-12 was used with an expired calibration certificate (3 days). Balance withdrawn; recalibration in progress. IPC data for GRN-0218 under review."}', 3410, 772, 178, NULL);
INSERT INTO traces (id, timestamp, user_input, retrieved_chunks, prompt_version, model_output, latency_ms, input_tokens, output_tokens, error) VALUES ('7873a828-cd55-5cd9-b0a7-568eab412bee', strftime('%Y-%m-%dT', 'now', '-5 days') || '11' || strftime(':%M:%SZ', 'now'), 'During cleaning verification of Reactor R-06, swab samples from two internal locations exceeded the cleaning acceptance limit for active residue by 12% and 18% respectively. A third location passed.', '[]', 'v1', '{"classification": "Cleaning", "severity": "High", "impact": "Reactor R-06 cannot be used for the next product campaign. Cross-contamination risk if the reactor is used before re-cleaning and re-verification.", "immediate_action": "Quarantine reactor R-06. Initiate re-cleaning per the validated cleaning procedure. Escalate to QA and Manufacturing management.", "qa_escalation": true, "missing_info": "Identity of the next scheduled product in R-06 and its therapeutic window.", "draft_summary": "Cleaning verification swabs at two of three locations in R-06 exceeded the active residue limit by up to 18%. Reactor quarantined; re-cleaning authorised by QA."}', 4340, 817, 199, NULL);
INSERT INTO traces (id, timestamp, user_input, retrieved_chunks, prompt_version, model_output, latency_ms, input_tokens, output_tokens, error) VALUES ('ca2ff9fb-c0f4-54f7-9621-aab108ffb3dc', strftime('%Y-%m-%dT', 'now', '-6 days') || '14' || strftime(':%M:%SZ', 'now'), 'A routine environmental monitoring air sample from Grade C corridor CC-07 returned a total viable count of 45 CFU/m³ against an action limit of 50 CFU/m³. The alert limit is 25 CFU/m³.', '[]', 'v1', '{"classification": "Environmental", "severity": "Low", "impact": "Count is above alert limit but below action limit. Trend monitoring should be reviewed. No immediate product impact identified.", "immediate_action": "Investigate potential root causes (gowning, cleaning frequency, HVAC). Increase monitoring frequency for CC-07 until three consecutive passing results are obtained.", "qa_escalation": false, "missing_info": "Recent trend data for CC-07 over the past 4 weeks.", "draft_summary": "EM air sample for CC-07 recorded 45 CFU/m\u00b3 \u2014 above alert limit (25) but below action limit (50). Enhanced monitoring and root cause investigation initiated."}', 3520, 779, 182, NULL);
INSERT INTO traces (id, timestamp, user_input, retrieved_chunks, prompt_version, model_output, latency_ms, input_tokens, output_tokens, error) VALUES ('8c106354-90ef-5e07-ac0e-7e49b95f3790', strftime('%Y-%m-%dT', 'now', '-6 days') || '16' || strftime(':%M:%SZ', 'now'), 'Batch release documentation for ORL-0521 was signed by a QA officer whose training record for the relevant SOP (SOP-QA-031) lapsed two weeks ago. The batch has not yet been shipped.', '[]', 'v1', '{"classification": "Documentation", "severity": "Medium", "impact": "Batch release may not be valid if signed by an officer whose training was lapsed. Potential GMP data integrity issue.", "immediate_action": "Do not ship the batch. Assess whether a qualified, currently trained QA officer must countersign or re-issue the release. Complete retraining for the original signatory.", "qa_escalation": true, "missing_info": "Whether the specific SOP content changed since the officer''s last training.", "draft_summary": "A batch release document for ORL-0521 was signed by a QA officer with a lapsed training record for SOP-QA-031. Batch held; QA management review in progress."}', 3890, 798, 191, NULL);
